const STREAMING_DEVICES = [
  { share: 76.7, made: 115, kwh: 0.150, remoteKwh: 0.019 }, // TV
  { share: 7.1, made: 30, kwh: 0.140, remoteKwh: 0.019 }, // Desktop
  { share: 11.3, made: 5, kwh: 0.002, remoteKwh: 0.012 }, // Phone
  { share: 4.8, made: 137, kwh: 0.002, remoteKwh: 0.012 }, // Tablet
];
const STREAMING_SHARE = STREAMING_DEVICES.reduce((sum, device) => sum + device.share, 0);
const streamingComponent = (key) => {
  const values = STREAMING_DEVICES.map((device) => device[key]);
  const average = STREAMING_DEVICES.reduce((sum, device) => sum + device.share * device[key], 0) / STREAMING_SHARE;
  return [Math.min(...values), average, Math.max(...values)];
};

